import java.util.Arrays;

final class CoinChangeRequest {
    private final int[] coins;
    private final int targetSum;

    CoinChangeRequest(int[] coins, int targetSum) {
        validateCoins(coins);
        validateTargetSum(targetSum);
        this.coins = Arrays.copyOf(coins, coins.length);
        this.targetSum = targetSum;
    }

    int[] coins() {
        return Arrays.copyOf(coins, coins.length);
    }

    int targetSum() {
        return targetSum;
    }

    private static void validateCoins(int[] coins) {
        if (coins == null) {
            throw new IllegalArgumentException("coins must not be null");
        }

        for (int coin : coins) {
            if (coin <= 0) {
                throw new IllegalArgumentException("coin values must be positive");
            }
        }
    }

    private static void validateTargetSum(int targetSum) {
        if (targetSum < 0) {
            throw new IllegalArgumentException("targetSum must not be negative");
        }
    }
}

public final class CoinChange {

    private CoinChange() {
    }

    static int count(int[] coins, int targetSum) {
        return ChangeCounter.countWays(new CoinChangeRequest(coins, targetSum));
    }

    public static void main(String[] args) {
        int[] coins = {1, 2, 3};
        int targetSum = 5;
        System.out.println(count(coins, targetSum));
    }
}

final class ChangeCounter {

    private ChangeCounter() {
    }

    static int countWays(CoinChangeRequest request) {
        int[] coins = request.coins();
        int targetSum = request.targetSum();
        int[] waysBySum = new int[targetSum + 1];
        waysBySum[0] = 1;

        for (int coin : coins) {
            for (int currentSum = coin; currentSum <= targetSum; currentSum++) {
                waysBySum[currentSum] += waysBySum[currentSum - coin];
            }
        }

        return waysBySum[targetSum];
    }
}

public final class CoinChangeSelfTest {

    private CoinChangeSelfTest() {
    }

    public static void main(String[] args) {
        assertCount(new int[] {1, 2, 3}, 5, 5);
        assertCount(new int[] {2, 5, 3, 6}, 10, 5);
        assertCount(new int[] {4}, 3, 0);
        assertRejects(new int[] {1, 0, 3}, 4);
        assertRejects(new int[] {1, 2, 3}, -1);
    }

    private static void assertCount(int[] coins, int targetSum, int expectedWays) {
        int actualWays = CoinChange.count(coins, targetSum);
        if (actualWays != expectedWays) {
            throw new AssertionError(
                "Expected " + expectedWays + " ways for target " + targetSum + " but got " + actualWays
            );
        }
    }

    private static void assertRejects(int[] coins, int targetSum) {
        try {
            CoinChange.count(coins, targetSum);
            throw new AssertionError("Expected invalid input to be rejected");
        } catch (IllegalArgumentException expected) {
            // Expected path.
        }
    }
}
